L["Play it, at its volume."] = "Abspielen, in seiner Lautstärke."
L["Play it, to see it (at no one)."] = "Abspielen, um es zu sehen (an niemanden gerichtet)."
L["Play this shot now (stand still). Press it again, or move, to stop."] = "Diese Aufnahme jetzt abspielen (steh still). Erneut drücken oder bewegen zum Stoppen."
L["Played by"] = "Abgespielt von"
